package com.diegonmarcos.cloudc3.pages

import kotlinx.serialization.json.Json
import kotlinx.serialization.json.JsonArray
import kotlinx.serialization.json.JsonObject
import kotlinx.serialization.json.JsonPrimitive
import kotlinx.serialization.json.contentOrNull
import kotlinx.serialization.json.intOrNull

/**
 * #1725 Infra > APIs > C3 MCP: the MCP servers of the C3 environment, every tool each lists and the c3-api route the tool maps
 * to, read from the `mcp_catalogue` block of data/api_providers.json (text in, models out). That block is GENERATED by
 * data/gen_c3_mcp.py from ac_cloud-c3-webserver/data/mcp-catalogue.json. These rows were Cloud C3 Webserver > API's MCP page and
 * the remote nodes of its Topology; the webserver shows only the phone now (it keeps the tools that act on the device), and every
 * field it showed is kept here. Nothing here names a server or a tool; [group] is the id of the API group whose page draws it.
 */
object C3Mcp {

    data class Tool(val tool: String, val route: String, val tree: String, val node: String, val legacy: String?) {
        /** The generator found no API route for the tool's node: it is an MCP-only tool (the Topology's mcp_only badge). */
        val mcpOnly: Boolean get() = route.contains("no API route")
    }

    data class Server(
        val name: String, val endpoint: String, val auth: String, val aliases: List<String>, val api: String,
        val toolsCount: Int, val deviceTools: Int, val tools: List<Tool>,
    ) {
        /** The c3-api nodes this server's tools map to (the Topology's remote API nodes), each with its tools, in first-seen order. */
        fun apiNodes(): List<Pair<String, List<Tool>>> = tools.filter { !it.mcpOnly }.groupBy { it.node }.toList()
    }

    data class Decl(val group: String = "", val source: String = "", val servers: List<Server> = emptyList()) {
        val tools: Int get() = servers.sumOf { it.tools.size }
        val apiNodes: Int get() = servers.flatMap { s -> s.apiNodes().map { it.first } }.distinct().size
        fun summary(): String = "${servers.size} MCP servers - $tools tools listed - $apiNodes c3-api nodes - ${servers.sumOf { it.tools.count { t -> t.mcpOnly } }} MCP only"
    }

    private val json = Json { ignoreUnknownKeys = true; isLenient = true }

    /** Never throws: a missing or malformed block is an empty declaration. */
    fun parse(text: String): Decl {
        val root = runCatching { json.parseToJsonElement(text) }.getOrNull() as? JsonObject ?: return Decl()
        val block = root["mcp_catalogue"] as? JsonObject ?: return Decl()
        fun JsonObject.str(k: String) = (this[k] as? JsonPrimitive)?.contentOrNull
        fun JsonObject.int(k: String) = (this[k] as? JsonPrimitive)?.intOrNull ?: 0
        fun JsonObject.strs(k: String) = (this[k] as? JsonArray).orEmpty().mapNotNull { (it as? JsonPrimitive)?.contentOrNull }
        fun JsonObject.objs(k: String) = (this[k] as? JsonArray).orEmpty().mapNotNull { it as? JsonObject }
        val servers = block.objs("servers").mapNotNull { s ->
            val name = s.str("name")?.takeIf { it.isNotBlank() } ?: return@mapNotNull null
            Server(
                name = name, endpoint = s.str("endpoint").orEmpty(), auth = s.str("auth").orEmpty(), aliases = s.strs("aliases"), api = s.str("api").orEmpty(),
                toolsCount = s.int("tools_count"), deviceTools = s.int("device_tools"),
                tools = s.objs("tools").mapNotNull { t ->
                    val tool = t.str("tool")?.takeIf { it.isNotBlank() } ?: return@mapNotNull null
                    Tool(tool, t.str("route").orEmpty(), t.str("tree").orEmpty(), t.str("node").orEmpty(), t.str("legacy")?.takeIf { it.isNotBlank() })
                },
            )
        }
        return Decl(block.str("group").orEmpty(), block.str("source").orEmpty(), servers)
    }

    /** The lines of a server's own row; every declared field appears, an absent one says so. */
    fun lines(s: Server): List<String> = listOf(
        "Endpoint: ${s.endpoint.ifBlank { "not declared" }}",
        "Auth: ${s.auth.ifBlank { "not declared" }}",
        "API: ${s.api.ifBlank { "no API of its own" }}",
        "Aliases: ${s.aliases.joinToString(", ").ifBlank { "none" }}",
        "Tools: ${s.toolsCount}" + when {
            s.tools.isEmpty() && s.deviceTools == 0 -> " (listed by the server itself, tools/list)"
            s.deviceTools > 0 -> " - ${s.tools.size} listed here, ${s.deviceTools} act on the phone (Cloud C3 Webserver > API > MCP)"
            else -> " - ${s.tools.size} listed here"
        },
        "c3-api nodes: ${s.apiNodes().size}",
    )

    /** The lines of one tool's row: the API route it maps to, its tree path, its node and its old name. */
    fun lines(t: Tool): List<String> = listOf(
        "API route ${t.route.ifBlank { "not declared" }}",
        "tree ${t.tree.ifBlank { "not declared" }}",
        "node ${t.node.ifBlank { "not declared" }}",
        t.legacy?.let { "old name $it" }.orEmpty(),
    )
}
